USE retainiq;
SELECT 'fact_customer_status' table_name,COUNT(*) row_count FROM fact_customer_status UNION ALL SELECT 'dim_demographics',COUNT(*) FROM dim_demographics UNION ALL SELECT 'dim_location',COUNT(*) FROM dim_location UNION ALL SELECT 'dim_services',COUNT(*) FROM dim_services UNION ALL SELECT 'dim_account',COUNT(*) FROM dim_account UNION ALL SELECT 'dim_churn_detail',COUNT(*) FROM dim_churn_detail;
SELECT customer_id,COUNT(*) row_count FROM fact_customer_status GROUP BY customer_id HAVING COUNT(*)>1;
SELECT 'demographics' dimension,COUNT(*) orphan_rows FROM dim_demographics d LEFT JOIN fact_customer_status f ON d.customer_id=f.customer_id WHERE f.customer_id IS NULL UNION ALL SELECT 'location',COUNT(*) FROM dim_location d LEFT JOIN fact_customer_status f ON d.customer_id=f.customer_id WHERE f.customer_id IS NULL UNION ALL SELECT 'services',COUNT(*) FROM dim_services d LEFT JOIN fact_customer_status f ON d.customer_id=f.customer_id WHERE f.customer_id IS NULL UNION ALL SELECT 'account',COUNT(*) FROM dim_account d LEFT JOIN fact_customer_status f ON d.customer_id=f.customer_id WHERE f.customer_id IS NULL UNION ALL SELECT 'churn_detail',COUNT(*) FROM dim_churn_detail d LEFT JOIN fact_customer_status f ON d.customer_id=f.customer_id WHERE f.customer_id IS NULL;
SELECT COUNT(*) total_customers,SUM(churn_label='Yes') churned_customers,SUM(churn_label='No') non_churned_customers,ROUND(100*SUM(churn_label='Yes')/COUNT(*),2) churn_rate_pct,SUM(CASE WHEN churn_label='Yes' THEN total_revenue ELSE 0 END) revenue_at_risk FROM fact_customer_status;
SELECT a.contract,COUNT(*) customers,SUM(f.churn_label='Yes') churned_customers,ROUND(100*SUM(f.churn_label='Yes')/COUNT(*),2) churn_rate_pct,SUM(CASE WHEN f.churn_label='Yes' THEN f.total_revenue ELSE 0 END) revenue_at_risk FROM fact_customer_status f JOIN dim_account a ON f.customer_id=a.customer_id GROUP BY a.contract ORDER BY churn_rate_pct DESC;
SELECT a.payment_method,COUNT(*) customers,SUM(f.churn_label='Yes') churned_customers,ROUND(100*SUM(f.churn_label='Yes')/COUNT(*),2) churn_rate_pct FROM fact_customer_status f JOIN dim_account a ON f.customer_id=a.customer_id GROUP BY a.payment_method ORDER BY churn_rate_pct DESC;
SELECT s.internet_type,COUNT(*) customers,SUM(f.churn_label='Yes') churned_customers,ROUND(100*SUM(f.churn_label='Yes')/COUNT(*),2) churn_rate_pct,SUM(CASE WHEN f.churn_label='Yes' THEN f.total_revenue ELSE 0 END) revenue_at_risk FROM fact_customer_status f JOIN dim_services s ON f.customer_id=s.customer_id GROUP BY s.internet_type ORDER BY churn_rate_pct DESC;
SELECT satisfaction_score,COUNT(*) customers,SUM(churn_label='Yes') churned_customers,ROUND(100*SUM(churn_label='Yes')/COUNT(*),2) churn_rate_pct FROM fact_customer_status GROUP BY satisfaction_score ORDER BY satisfaction_score;
SELECT customer_id,cltv,CASE WHEN cltv>=5000 THEN 'High Value' WHEN cltv>=3500 THEN 'Medium Value' ELSE 'Low Value' END value_segment FROM fact_customer_status ORDER BY cltv DESC;
WITH high_value_customers AS (SELECT customer_id,cltv,total_revenue,satisfaction_score,churn_label FROM fact_customer_status WHERE cltv>=5000) SELECT COUNT(*) high_value_customers,SUM(churn_label='Yes') high_value_churned,ROUND(100*SUM(churn_label='Yes')/COUNT(*),2) high_value_churn_rate_pct FROM high_value_customers;
SELECT customer_id,cltv,RANK() OVER(ORDER BY cltv DESC) cltv_rank FROM fact_customer_status ORDER BY cltv_rank LIMIT 25;
SELECT f.customer_id,a.contract,f.total_revenue,SUM(f.total_revenue) OVER(PARTITION BY a.contract) contract_revenue,ROUND(100*f.total_revenue/SUM(f.total_revenue) OVER(PARTITION BY a.contract),2) contract_revenue_share_pct FROM fact_customer_status f JOIN dim_account a ON f.customer_id=a.customer_id ORDER BY contract_revenue DESC,f.total_revenue DESC LIMIT 50;
SELECT f.customer_id,f.cltv,f.total_revenue,f.monthly_charge,f.churn_score,f.satisfaction_score,a.contract,a.offer,s.internet_type,s.premium_tech_support FROM fact_customer_status f JOIN dim_account a ON f.customer_id=a.customer_id JOIN dim_services s ON f.customer_id=s.customer_id WHERE f.churn_label='Yes' ORDER BY f.cltv DESC LIMIT 25;
SELECT f.customer_id,f.customer_status,f.churn_label,f.churn_score,f.cltv,f.monthly_charge,f.total_revenue,f.satisfaction_score,a.contract,a.payment_method,a.offer,s.internet_type,s.premium_tech_support,d.gender,d.age,d.senior_citizen,l.state,l.city FROM fact_customer_status f JOIN dim_account a ON f.customer_id=a.customer_id JOIN dim_services s ON f.customer_id=s.customer_id JOIN dim_demographics d ON f.customer_id=d.customer_id JOIN dim_location l ON f.customer_id=l.customer_id;
